-- pronouns, demonstratives …) and every form of a noun or verb the Qurʾān uses
-- 25 times or more — a learner meets those on every page. Built from km_quran
-- qr_word_occurrence (QAC morphology), stored bare (no vowels, hamza seats folded).
CREATE TABLE IF NOT EXISTS ar_common_word (
  bare TEXT PRIMARY KEY, kind TEXT NOT NULL, lemma TEXT, quran_freq INTEGER
);
DELETE FROM ar_common_word;
